k-name,.weather{display:flex;align-items:center;gap:12px}.flag{font-size:24px}.track-name strong{display:block;font:800 20px var(--display);letter-spacing:1.3px}.track-name small,.weather small{display:block;color:#80919a;font:9px var(--mono);letter-spacing:1px;margin-top:1px}.weather>span{font-size:22px;color:#f5ca67}.weather strong{font:700 14px var(--mono)}.canvas-wrap{position:relative;width:100%;height:clamp(360px,44vw,510px);overflow:hidden;background:#85b4c3}canvas{display:block;width:100%;height:100%;touch-action:none}.race-overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#06121bb8,#06121b38 80%),linear-gradient(0deg,#07141c85,transparent 55%);transition:opacity .4s,visibility .4s}.race-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{width:min(390px,78%);margin-right:auto;margin-left:8%;text-shadow:0 2px 14px #0005}.overlay-kicker{font:10px var(--mono);letter-spacing:1.3px;color:#e2ebdf}.overlay-kicker .live-dot{margin-right:8px}.overlay-card h2{font:800 clamp(40px,5vw,58px)/.87 var(--display);text-transform:uppercase;margin:16px 0 12px;letter-spacing:.3px}.overlay-card p{font-size:12px;color:#dae2df;margin:0 0 23px}.start-button{border:0;background:var(--lime);color:#14200c;padding:14px 18px;font:800 12px var(--body);letter-spacing:.7px;cursor:pointer;transition:transform .15s,background .15s}.start-button span{font-size:17px;margin-left:20px}.start-button:hover{background:#d9ff76;transform:translateY(-2px)}.key-hint{margin-top:19px;color:#ccd5d5;font:10px var(--mono);display:flex;align-items:center;gap:5px}.key-hint kbd{width:19px;height:20px;border:1px solid #ffffff55;display:grid;place-items:center;border-radius:2px;font:10px var(--mono)}.key-hint span{margin-left:5px;color:#d0d9d7}.countdown{position:absolute;inset:0;display:grid;place-items:center;background:#06131d50;font:900 110px var(--display);color:white;text-shadow:0 4px 30px #000}.hidden{display:none!important}.finish-banner{position:absolute;top:17%;left:50%;transform:translateX(-50%);background:var(--lime);color:#101a11;padding:11px 22px;font:900 24px var(--display);letter-spacing:1.5px;white-space:nowrap;box-shadow:0 6px 26px #0005}.race-footer{height:35px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;background:#091720;color:#87979f;font:9px var(--mono);letter-spacing:.7px}.race-footer>span:first-child{display:flex;align-items:center;gap:8px}.race-footer>span:last-child{font-size:8px}.status-dot{width:6px;height:6px;border-radius:50%;background:#73848b}.status-dot.active{background:var(--lime);box-shadow:0 0 7px var(--lime)}.telemetry{padding:17px 17px 13px;display:flex;flex-direction:column}.telemetry-title,.lap-track-head,.leaderboard-title{display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:1px;color:#9babb0}.telemetry-live{color:var(--lime);font-size:9px}.telemetry-live .live-dot{width:5px;height:5px;margin-right:5px}.speed-block{padding:18px 0 15px;border-bottom:1px solid var(--line)}.speed-readout{display:flex;align-items:baseline;gap:10px}.speed-readout span{font:800 70px/.9 var(--display);letter-spacing:1px}.speed-readout small{font:10px var(--mono);color:#8e9da3}.speed-gauge{margin-top:10px}.gauge-track{height:5px;background:#23343d;overflow:hidden}.gauge-fill{width:0;height:100%;background:linear-gradient(90deg,var(--lime),#f5cb4e,var(--red));transition:width .12s}.gauge-labels{display:flex;justify-content:space-between;color:#697b83;font:8px var(--mono);padding-top:5px}.telemetry-grid{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line)}.data-cell{min-height:62px;padding:12px 0 9px}.data-cell:nth-child(odd){border-right:1px solid var(--line)}.data-cell:nth-child(even){padding-left:13px}.data-cell:nth-child(-n+2){border-bottom:1px solid var(--line)}.data-cell>span{display:block;color:#84969e;font:8px var(--mono);letter-spacing:.8px;margin-bottom:5px}.data-cell strong{font:700 21px var(--display)}.data-cell strong small{font:10px var(--mono);color:#75868d}.data-cell .time-value{font:12px var(--mono);letter-spacing:-.3px}.lap-track{padding:14px 0;border-bottom:1px solid var(--line)}.lap-track-head{font-size:8px}.lap-track-head strong{color:var(--white);font:10px var(--mono)}.progress-bar{height:3px;background:#283941;margin-top:9px}.progress-bar i{display:block;height:100%;width:0;background:var(--lime);transition:width .2s}.leaderboard{padding-top:13px;flex:1}.leaderboard-title{font-size:9px;color:#dbe2df}.leaderboard-title span{font-size:8px;color:#778991}.leaderboard ol{list-style:none;padding:0;margin:8px 0 0}.leaderboard li{height:27px;display:grid;grid-template-columns:21px 1fr auto;align-items:center;border-bottom:1px solid #ffffff0b;font:10px var(--mono);color:#aab8bc}.leaderboard li:first-child{color:var(--lime)}.leaderboard li.player{color:#fff}.leaderboard li .driver-number{color:#61747c;font-size:8px}.leaderboard li .driver-gap{font-size:8px;color:#72848b}.leaderboard li.player .driver-name:after{content:'  YOU';font-size:7px;color:var(--red)}.telemetry-bottom{border-top:1px solid var(--line);padding-top:12px;display:flex;justify-content:space-between;color:#778a91;font:8px var(--mono);letter-spacing:.5px}.telemetry-bottom b{font-weight:400}.telemetry-bottom i{font-style:normal;color:var(--lime);margin-left:4px}.page-footer{padding:22px 0 18px;display:flex;justify-content:space-between;color:#63757d;font:8px var(--mono);letter-spacing:1px}.page-footer b{color:var(--red);font-size:12px}.mobile-controls{display:none}
