(() => {
  const canvas = document.getElementById('raceCanvas');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const LAP = 5200, TOTAL = LAP * 3, MAX_SPEED = 320;
  const drivers = [
