+          ctx.strokeStyle='#e7e7d9';ctx.lineWidth=Math.max(1,d1*2);ctx.beginPath();ctx.moveTo(g1.cx,g1.y);ctx.lineTo(g2.cx,g2.y);ctx.stroke();
