+        // wing and body
+        ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-w*.65,-h*.43);ctx.lineTo(w*.65,-h*.43);ctx.lineTo(w*.5,-h*.2);ctx.lineTo(w*.39,h*.33);ctx.lineTo(w*.25,h*.48);ctx.lineTo(-w*.25,h*.48);ctx.lineTo(-w*.39,h*.33);ctx.lineTo(-w*.5,-h*.2);ctx.closePath();ctx.fill();
