+        const rank=sorted.findIndex(d=>d.player)+1;$('positionValue').innerHTML=`${rank}<small> / 8</small>`;
+        $('leaderboardList').innerHTML=sorted.map((d,i)=>`<li class="${d.player?'player':''}"><span class="driver-number">${String(i+1).padStart(2,'0')}</span><span class="driver-name">${d.name}</span><span class="driver-gap">${i===0?'LEADER':d.distance>state.distance?`+${Math.round(d.distance-state.distance)}m`:`-${Math.round(state.distance-d.distance)}m`}</span></li>`).join('');
